function cleanTranscript(text) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/(\b╨Ш\s+╤П\s*){2,}/giu, ' ');
  t = t.replace(/(\b╨п\s+╨╕\s*){2,}/giu, ' ');
  t = t.replace(/\b╨╕\s+╤П\s+╨╕\s+╤П\b/giu, ' ');
  t = t.replace(/\b╨╛╤Б╤В╨░╨▓╨╗╤О\b/giu, ' ');
  t = t.replace(/\b(╤Г╨│╤Г|╨░╨│╨░|╤Н╤Н╤Н|╤Н╨╝|╨╝╨╝╨╝|╤Е╨╝)\b/giu, ' ');
  t = t.replace(/\b(\w+)(\s+\1){3,}/giu, '$1');
  t = t.replace(/(\w{4,}?)\1{3,}/giu, '$1');
  t = t.replace(/\s+([,.!?;:])/g, '$1');
  t = t.replace(/([,.!?;:])\1{2,}/g, '$1');
  t = t.replace(/\s{2,}/g, ' ').trim();
  return t;
}

