async function processVideo(item, index) {
  const json      = item.json;
  const videoId   = json.video_id;
  const videoUrl  = json.video_url;

  const tmpDir    = `/tmp/${videoId}`;
  const startTime = Date.now();

  let duration = 0, downloadSeconds = 0, convertSeconds = 0, apiSeconds = 0, durationCheckError = '';

  const language = detectLanguage(json.channel_topic, json.channel_name);
  const prompt   = buildWhisperPrompt(json.channel_topic);

  // ╨Я╤А╨╛╨▓╨╡╤А╨║╨╕ ╤Б╤В╨╛╨┐-╤Д╨╗╨░╨│╨╛╨▓
  if (RATE_LIMITED) {
    console.log(`[SKIP_RATE_LIMITED] id=${videoId}`);
    return rateLimitResponse(json, index, 'BATCH_ALREADY_RATE_LIMITED');
