  if (AUTH_ERROR) {
    console.log(`[SKIP_AUTH_ERROR] id=${videoId}`);
    return authErrorResponse(json, index, 'BATCH_ALREADY_AUTH_ERROR');
  }

  console.log(`[LangDetect] id=${videoId} channel="${json.channel_name}" topic="${json.channel_topic}" тЖТ language=${language} prompt_len=${prompt.length}`);

  try {
    await fsp.mkdir(tmpDir, { recursive: true });

    // ╨Ф╨Ы╨Ш╨в╨Х╨Ы╨м╨Э╨Ю╨б╨в╨м
    try {
      const { stdout } = await execAsync(
        `yt-dlp --js-runtimes deno --remote-components ejs:github --cookies /tmp/cookies.txt --no-playlist --get-duration "${videoUrl}"`,
        { timeout: 60000, maxBuffer: 10 * 1024 * 1024 }
      );
      duration = parseDuration(stdout);
    } catch (error) {
      duration = 0;
      durationCheckError = String(error.message || error).substring(0, 500);

      // 403 ╤Г╨╢╨╡ ╨╜╨░ ╤Н╤В╨░╨┐╨╡ get-duration
      if (isAuthError(durationCheckError)) {
        AUTH_ERROR = true;
        await cleanup(tmpDir);
        console.log(`[AUTH_ERROR] id=${videoId} тАФ cookies ╨┐╤А╨╛╤В╤Г╤Е╨╗╨╕`);
        return authErrorResponse(json, index, 'YOUTUBE_403 (get-duration): ' + durationCheckError.substring(0, 300));
      }
    }

    // ╨б╨Ы╨Ш╨и╨Ъ╨Ю╨Ь ╨Ф╨Ы╨Ш╨Э╨Э╨Ю╨Х
    if (!durationCheckError && duration > MAX_DURATION_SECONDS) {
      await cleanup(tmpDir);
      const durationStr = formatDuration(duration);
      console.log(`[SKIP_TOO_LONG] id=${videoId} duration=${durationStr}`);
      return {
        json: {
          ...json,
          text_to_translate: '',
          status: 'too_long',
          duration_seconds: duration,
          is_successful: false,
          mark_processed: true,
          is_error: true,
          error_message: `╨Ф╨Ы╨Ш╨Э╨Э╨Ю╨Х_╨Т╨Ш╨Ф╨Х╨Ю: ${durationStr} (> 1 ╤З╨░╤Б╨░)`,
          skip_video_file: true,
        },
        pairedItem: { item: index }
      };
    }

    // ╨б╨Ъ╨Р╨з╨Ш╨Т╨Р╨Э╨Ш╨Х
    const downloadStart = Date.now();
    await execAsync(
      `yt-dlp --js-runtimes deno --remote-components ejs:github --cookies /tmp/cookies.txt -f bestaudio/best --no-playlist "${videoUrl}" -o "${tmpDir}/audio.%(ext)s"`,
      { timeout: 600000, maxBuffer: 100 * 1024 * 1024 }
    );
    downloadSeconds = Number(((Date.now() - downloadStart) / 1000).toFixed(2));

    const files = await fsp.readdir(tmpDir);
    const audioFile = files.find(f => f.startsWith('audio.') && !f.endsWith('.json'));
    if (!audioFile) throw new Error('╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨┐╨╛╨╗╤Г╤З╨╕╤В╤М ╨░╤Г╨┤╨╕╨╛╤Д╨░╨╣╨╗');
    const audioPath = `${tmpDir}/${audioFile}`;

    // WAV
    const wavPath = `${tmpDir}/audio.wav`;
    const convertStart = Date.now();
    await execAsync(
      `ffmpeg -i "${audioPath}" -ar 16000 -ac 1 -c:a pcm_s16le "${wavPath}" -y`,
      { timeout: 300000, maxBuffer: 50 * 1024 * 1024 }
    );
    convertSeconds = Number(((Date.now() - convertStart) / 1000).toFixed(2));

    // WORKER
    const apiStart = Date.now();
    const promptEscaped = prompt.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    const promptPart = prompt ? ` -F "prompt=${promptEscaped}"` : '';

    const curlCmd =
      `curl -sS -X POST "${WORKER_URL}" ` +
      `-F "file=@${wavPath};type=audio/wav" ` +
      `-F "language=${language}"` +
      promptPart;

    const { stdout } = await execAsync(curlCmd, { timeout: 600000, maxBuffer: 500 * 1024 * 1024 });
    apiSeconds = Number(((Date.now() - apiStart) / 1000).toFixed(2));

    let parsed;
    try { parsed = JSON.parse(stdout); }
    catch { throw new Error(`╨Э╨╡╨║╨╛╤А╤А╨╡╨║╤В╨╜╤Л╨╣ ╨╛╤В╨▓╨╡╤В Worker: ${String(stdout).substring(0, 300)}`); }

    if (parsed.error) {
      const errorText = typeof parsed.error === 'string'
        ? parsed.error
        : parsed.error.message || JSON.stringify(parsed.error);

      // 429
      if (errorText.includes('429') || errorText.includes('4006') || errorText.includes('daily free allocation')) {
        RATE_LIMITED = true;
        await cleanup(tmpDir);
        console.log(`[RATE_LIMIT_429] id=${videoId}`);
        return rateLimitResponse(json, index, 'CLOUDFLARE_429: ' + errorText.substring(0, 300));
      }

      throw new Error(errorText);
