    // ╨в╨Х╨Ъ╨б╨в
    const rawTranscript = String(parsed.text || parsed.transcript || '').trim();
    const transcript = cleanTranscript(rawTranscript);
    await cleanup(tmpDir);

    const wordCount = transcript ? transcript.split(/\s+/).filter(Boolean).length : 0;

    if (!transcript || transcript.length < MIN_CHARS || wordCount < MIN_WORDS) {
      return {
        json: {
          ...json,
          text_to_translate: '',
          status: !transcript ? '╨Э╨╡╤В ╤А╨╡╤З╨╕ ╨▓ ╨▓╨╕╨┤╨╡╨╛' : `╨Ь╤Г╤Б╨╛╤А╨╜╤Л╨╣ ╤В╤А╨░╨╜╤Б╨║╤А╨╕╨┐╤В (chars=${transcript.length}, words=${wordCount})`,
          duration_seconds: duration,
          is_successful: false,
          mark_processed: true,
          is_error: true,
          error_message: !transcript
            ? '╨Э╨Х╨в_╨в╨Х╨Ъ╨б╨в╨Р: ╤В╤А╨░╨╜╤Б╨║╤А╨╕╨▒╨░╤Ж╨╕╤П ╨▓╨╡╤А╨╜╤Г╨╗╨░ ╨┐╤Г╤Б╤В╨╛╨╣ ╤В╨╡╨║╤Б╤В'
            : `╨Ь╨г╨б╨Ю╨а_╨в╨а╨Р╨Э╨б╨Ъ╨а╨Ш╨Я╨в╨Р: chars=${transcript.length}, words=${wordCount}, language=${language}`,
          skip_video_file: true,
        },
        pairedItem: { item: index }
      };
    }

    return {
      json: {
        ...json,
        text_to_translate: transcript,
        status: '╨в╤А╨░╨╜╤Б╨║╤А╨╕╨┐╤Ж╨╕╤П ╤Г╤Б╨┐╨╡╤И╨╜╨░',
        duration_seconds: duration,
        is_successful: true,
        mark_processed: true,
        is_error: false,
        error_message: '',
        skip_video_file: false,
        language_used: language,
        whisper_prompt_used: prompt.length > 0,
      },
      pairedItem: { item: index }
    };

  } catch (error) {
    await cleanup(tmpDir);
    const errorText = String(error.message || error).substring(0, 1000);

    // 429 ╨▓ catch
    if (errorText.includes('429') || errorText.includes('4006') || errorText.includes('daily free allocation')) {
      RATE_LIMITED = true;
      console.log(`[RATE_LIMIT_429_outer] id=${videoId}`);
      return rateLimitResponse(json, index, 'CLOUDFLARE_429 (outer): ' + errorText.substring(0, 300));
    }

    // 403 / cookies ╨▓ catch
    if (isAuthError(errorText)) {
      AUTH_ERROR = true;
      console.log(`[AUTH_ERROR_outer] id=${videoId}`);
      return authErrorResponse(json, index, 'YOUTUBE_403 (outer): ' + errorText.substring(0, 300));
    }

    return {
      json: {
        ...json,
        text_to_translate: '',
        status: `╨Ю╤И╨╕╨▒╨║╨░ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╤П: ${errorText}`,
        duration_seconds: duration,
        is_successful: false,
        mark_processed: true,
        is_error: true,
        error_message: errorText,
        skip_video_file: true,
        language_used: language,
      },
      pairedItem: { item: index }
