  }
}

// ╨Я╨Р╨а╨Р╨Ы╨Ы╨Х╨Ы╨м╨Э╨Р╨п ╨Ю╨С╨а╨Р╨С╨Ю╨в╨Ъ╨Р (╤Б╤В╨╛╨┐ ╨┐╤А╨╕ 429 ╨╕╨╗╨╕ AUTH_ERROR)
const items = $input.all();

async function runPool(items, concurrency, processor) {
  const results = new Array(items.length);
  let nextIndex = 0;

  async function worker() {
    while (true) {
      if (RATE_LIMITED || AUTH_ERROR) {
        const idx = nextIndex++;
        if (idx >= items.length) break;
        if (RATE_LIMITED) {
          results[idx] = rateLimitResponse(items[idx].json, idx, 'BATCH_STOPPED_BY_429');
        } else {
          results[idx] = authErrorResponse(items[idx].json, idx, 'BATCH_STOPPED_BY_AUTH_ERROR');
        }
        continue;
      }

      const index = nextIndex++;
      if (index >= items.length) break;
      results[index] = await processor(items[index], index);
    }
  }

  await Promise.all(Array.from({ length: concurrency }, () => worker()));
  return results;
}

const results = await runPool(items, 2, processVideo);

return results.filter(Boolean);
